function cart(state, action) {
  switch (action.type) {
    case 'add':
      return [...state, action.item]
    case 'remove':
      return state.filter(
        (i) => i.id !== action.id,
      )
    default:
      return state
  }
}
const [items, dispatch] =
  useReducer(cart, [])

function useDebounce(value, ms) {
  const [v, setV] = useState(value)
  useEffect(() => {
    const t = setTimeout(
      () => setV(value), ms,
    )
    return () => clearTimeout(t)
  }, [value, ms])
  return v
}

