import functools, time

def timed(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = fn(*args, **kwargs)
        log(fn.__name__,
            time.perf_counter() - start)
        return result
    return wrapper

def batches(path, size=1000):
    batch = []
    with open(path) as f:
        for line in f:
            batch.append(line)
            if len(batch) == size:
                yield batch
                batch = []
    if batch:
        yield batch

